+/// Serialize stream metrics like Pydantic's recursive `exclude_none=True`.
+pub fn serialize_stream_metrics<S>(
+    metrics: &Option<PerRequestMetrics>,
+    serializer: S,
+) -> Result<S::Ok, S::Error>

